// Tab Switching
        function switchTab(tab) {
            ['pacer', 'bolt'].forEach(t => {
                const mod = document.getElementById('module-' + t);
                const btn = document.getElementById('tab-btn-' + t);
                if (mod) mod.classList.toggle('hidden', t !== tab);
                if (btn) {
                    if (t === tab) {
                        btn.className = 'flex-1 min-w-[140px] py-2.5 px-3 rounded-xl text-xs font-bold transition-all shadow-sm bg-white text-slate-900 border border-slate-200';
                    } else {
                        btn.className = 'flex-1 min-w-[140px] py-2.5 px-3 rounded-xl text-xs font-bold transition-all text-slate-600 hover:text-slate-900';
                    }
                }
            });
        }

        // Web Audio Chime Synthesizer
        let audioCtx = null;
        let soundEnabled = true;

        function playTone(freq, duration) {
            if (!soundEnabled) return;
            try {
                const AudioCtxClass = window.AudioContext || window.webkitAudioContext;
                if (!AudioCtxClass) return;
                if (!audioCtx) audioCtx = new AudioCtxClass();
                if (audioCtx.state === 'suspended') audioCtx.resume().catch(() => {});

                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                const now = audioCtx.currentTime;

                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq, now);
                gain.gain.setValueAtTime(0.12, now);
                gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.start(now);
                osc.stop(now + duration);
            } catch (e) {}
        }

        function toggleAudioChimes() {
            soundEnabled = !soundEnabled;
            const btnText = document.getElementById('audio-text');
            if (btnText) btnText.innerText = 'Audio Chimes: ' + (soundEnabled ? 'On' : 'Off');
        }

        // Module 1: Coherence Pacer
        let pacerInterval = null;
        let sessionTimerInterval = null;
        let isPacing = false;
        let pacerPhase = 'inhale';
        let cycleCount = 0;
        let sessionSeconds = 0;

        let currentPreset = {
            inhale: 5.5,
            hold1: 0,
            exhale: 5.5,
            hold2: 0,
            bpm: 5.45
        };

        function setPreset(type) {
            resetPacer();
            ['resonance', 'box', '478', 'calm'].forEach(p => {
                const el = document.getElementById('preset-' + p);
                if (el) {
                    if (p === type) {
                        el.className = 'p-3 rounded-xl border border-teal-500 bg-teal-50 text-teal-900 text-xs font-bold transition-all';
                    } else {
                        el.className = 'p-3 rounded-xl border border-slate-200 bg-slate-50 text-slate-700 hover:border-slate-300 text-xs font-bold transition-all';
                    }
                }
            });

            if (type === 'resonance') {
                currentPreset = { inhale: 5.5, hold1: 0, exhale: 5.5, hold2: 0, bpm: 5.5 };
            } else if (type === 'box') {
                currentPreset = { inhale: 4.0, hold1: 4.0, exhale: 4.0, hold2: 4.0, bpm: 3.75 };
            } else if (type === '478') {
                currentPreset = { inhale: 4.0, hold1: 7.0, exhale: 8.0, hold2: 0, bpm: 3.16 };
            } else if (type === 'calm') {
                currentPreset = { inhale: 4.0, hold1: 0, exhale: 6.0, hold2: 0, bpm: 6.0 };
            }

            const bpmEl = document.getElementById('breath-bpm-badge');
            if (bpmEl) bpmEl.innerText = currentPreset.bpm.toFixed(1) + ' BPM';
        }

        function togglePacer() {
            if (isPacing) {
                resetPacer();
            } else {
                startPacer();
            }
        }

        function startPacer() {
            isPacing = true;
            const btn = document.getElementById('btn-pacer-toggle');
            if (btn) {
                btn.innerText = 'Pause Pacer';
                btn.className = 'px-8 py-3.5 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-xl transition text-xs uppercase tracking-widest shadow-md';
            }
            sessionTimerInterval = setInterval(() => {
                sessionSeconds++;
                const mins = Math.floor(sessionSeconds / 60).toString().padStart(2, '0');
                const secs = (sessionSeconds % 60).toString().padStart(2, '0');
                const sessEl = document.getElementById('session-duration');
                if (sessEl) sessEl.innerText = mins + ':' + secs;
            }, 1000);

            runPacerPhase('inhale');
        }

        function runPacerPhase(phase) {
            if (!isPacing) return;
            const orb = document.getElementById('breath-orb');
            const phaseText = document.getElementById('breath-phase-text');
            const timerText = document.getElementById('breath-timer-text');

            let duration = 5.5;
            let nextPhase = 'exhale';

            if (phase === 'inhale') {
                duration = currentPreset.inhale;
                if (phaseText) phaseText.innerText = 'Inhale';
                if (orb) orb.className = 'w-48 h-48 rounded-full border-4 border-teal-500 bg-gradient-to-br from-teal-100 to-teal-200 flex flex-col items-center justify-center transition-all ease-in-out transform scale-125 shadow-2xl';
                playTone(440, 0.4);
                nextPhase = currentPreset.hold1 > 0 ? 'hold1' : 'exhale';
            } else if (phase === 'hold1') {
                duration = currentPreset.hold1;
                if (phaseText) phaseText.innerText = 'Hold';
                if (orb) orb.className = 'w-48 h-48 rounded-full border-4 border-amber-500 bg-gradient-to-br from-amber-100 to-amber-200 flex flex-col items-center justify-center transition-all ease-in-out transform scale-125 shadow-2xl';
                playTone(554.37, 0.25);
                nextPhase = 'exhale';
            } else if (phase === 'exhale') {
                duration = currentPreset.exhale;
                if (phaseText) phaseText.innerText = 'Exhale';
                if (orb) orb.className = 'w-48 h-48 rounded-full border-4 border-teal-500 bg-gradient-to-br from-teal-50 to-teal-100 flex flex-col items-center justify-center transition-all ease-in-out transform scale-90 shadow-md';
                playTone(329.63, 0.5);
                nextPhase = currentPreset.hold2 > 0 ? 'hold2' : 'inhale';
            } else if (phase === 'hold2') {
                duration = currentPreset.hold2;
                if (phaseText) phaseText.innerText = 'Hold (Empty)';
                if (orb) orb.className = 'w-48 h-48 rounded-full border-4 border-slate-400 bg-gradient-to-br from-slate-100 to-slate-200 flex flex-col items-center justify-center transition-all ease-in-out transform scale-90 shadow-md';
                playTone(293.66, 0.25);
                nextPhase = 'inhale';
            }

            if (orb) orb.style.transitionDuration = (duration * 1000) + 'ms';
            if (timerText) timerText.innerText = duration.toFixed(1) + 's';

            pacerInterval = setTimeout(() => {
                if (nextPhase === 'inhale') {
                    cycleCount++;
                    const cEl = document.getElementById('cycle-count');
                    if (cEl) cEl.innerText = cycleCount;
                }
                runPacerPhase(nextPhase);
            }, duration * 1000);
        }

        function resetPacer() {
            isPacing = false;
            clearTimeout(pacerInterval);
            clearInterval(sessionTimerInterval);
            pacerInterval = null;
            sessionTimerInterval = null;
            sessionSeconds = 0;
            cycleCount = 0;

            const btn = document.getElementById('btn-pacer-toggle');
            const orb = document.getElementById('breath-orb');
            const phaseText = document.getElementById('breath-phase-text');
            const timerText = document.getElementById('breath-timer-text');
            const cEl = document.getElementById('cycle-count');
            const sessEl = document.getElementById('session-duration');

            if (btn) {
                btn.innerText = 'Start Pacer';
                btn.className = 'px-8 py-3.5 bg-teal-600 hover:bg-teal-500 text-white font-black rounded-xl transition text-xs uppercase tracking-widest shadow-md';
            }
            if (orb) {
                orb.className = 'w-48 h-48 rounded-full border-4 border-teal-500 bg-gradient-to-br from-teal-50 to-teal-100 flex flex-col items-center justify-center transition-all duration-300 transform scale-100 shadow-xl';
                orb.style.transitionDuration = '300ms';
            }
            if (phaseText) phaseText.innerText = 'Ready';
            if (timerText) timerText.innerText = '5.5s';
            if (cEl) cEl.innerText = '0';
            if (sessEl) sessEl.innerText = '00:00';
        }

        // Module 2: BOLT Stopwatch
        let boltRunning = false;
        let boltStartTime = 0;
        let boltInterval = null;
        let lastBoltScore = 0;

        function toggleBoltStopwatch() {
            if (boltRunning) {
                stopBolt();
            } else {
                startBolt();
            }
        }

        function startBolt() {
            boltRunning = true;
            boltStartTime = performance.now();
            const btn = document.getElementById('btn-bolt-toggle');
            const hint = document.getElementById('bolt-hint');
            if (btn) {
                btn.innerText = 'Stop (First Urge)';
                btn.className = 'px-8 py-3.5 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-xl transition text-xs uppercase tracking-widest shadow-md animate-pulse';
            }
            if (hint) hint.innerText = 'Pinch nose. Stop at the VERY FIRST physical urge or swallow reflex.';

            boltInterval = setInterval(() => {
                const elapsed = (performance.now() - boltStartTime) / 1000;
                const disp = document.getElementById('bolt-stopwatch-display');
                if (disp) disp.innerText = elapsed.toFixed(1) + 's';
            }, 100);
        }

        function stopBolt() {
            boltRunning = false;
            clearInterval(boltInterval);
            boltInterval = null;
            const elapsed = (performance.now() - boltStartTime) / 1000;
            lastBoltScore = elapsed;

            const btn = document.getElementById('btn-bolt-toggle');
            const hint = document.getElementById('bolt-hint');
            const badge = document.getElementById('bolt-tier-badge');
            const evalText = document.getElementById('bolt-clinical-evaluation');

            if (btn) {
                btn.innerText = 'Retest BOLT';
                btn.className = 'px-8 py-3.5 bg-teal-600 hover:bg-teal-500 text-white font-black rounded-xl transition text-xs uppercase tracking-widest shadow-md';
            }
            if (hint) hint.innerText = 'Your breathing should resume calmly. If gasping, you held past the first urge.';

            let tier = 'Optimal (30s+)', cls = 'bg-emerald-100 text-emerald-800', note = '';
            if (elapsed < 10) {
                tier = 'Severely Low (< 10s)';
                cls = 'bg-rose-100 text-rose-800';
                note = 'Indicates high chemoreceptor hypersensitivity to CO2 and habitual over-breathing. Practice nasal-only breathing 24/7 and 5.5s resonance pacing.';
            } else if (elapsed < 20) {
                tier = 'Compromised (10-20s)';
                cls = 'bg-amber-100 text-amber-800';
                note = 'Moderate breathlessness during physical exertion. Target 10-15 minutes of Box Breathing daily to reset medullary CO2 sensitivity.';
            } else if (elapsed < 30) {
                tier = 'Moderate (20-30s)';
                cls = 'bg-teal-100 text-teal-800';
                note = 'Acceptable baseline. You have adequate CO2 tolerance and normal ventilatory efficiency during resting states.';
            } else {
                tier = 'Optimal Adaptation (30s+)';
                cls = 'bg-emerald-100 text-emerald-800';
                note = 'Superior ventilatory efficiency. Your central chemoreceptors tolerate physiological CO2 buffering, maximizing the Bohr effect.';
            }

            if (badge) {
                badge.innerText = tier;
                badge.className = 'px-3 py-1 rounded-full text-xs font-black uppercase ' + cls;
            }
            if (evalText) evalText.innerText = note;
        }

        function resetBolt() {
            boltRunning = false;
            clearInterval(boltInterval);
            boltInterval = null;
            lastBoltScore = 0;
            const disp = document.getElementById('bolt-stopwatch-display');
            const btn = document.getElementById('btn-bolt-toggle');
            const hint = document.getElementById('bolt-hint');
            const badge = document.getElementById('bolt-tier-badge');
            const evalText = document.getElementById('bolt-clinical-evaluation');

            if (disp) disp.innerText = '0.0s';
            if (btn) {
                btn.innerText = 'Start Test';
                btn.className = 'px-8 py-3.5 bg-teal-600 hover:bg-teal-500 text-white font-black rounded-xl transition text-xs uppercase tracking-widest shadow-md';
            }
            if (hint) hint.innerText = 'Press "Start Test" or tap Spacebar immediately after exhaling normally.';
            if (badge) {
                badge.innerText = 'Awaiting Test';
                badge.className = 'px-3 py-1 rounded-full text-xs font-black uppercase bg-slate-200 text-slate-800';
            }
            if (evalText) evalText.innerText = 'A BOLT score of 30+ seconds reflects optimal ventilatory chemoreceptor sensitivity and normal arterial oxygen saturation efficiency.';
        }

        // Spacebar shortcut for BOLT stopwatch
        window.addEventListener('keydown', (e) => {
            if (e.code === 'Space' && !document.getElementById('module-bolt')?.classList.contains('hidden')) {
                if (document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA') {
                    e.preventDefault();
                    toggleBoltStopwatch();
                }
            }
        });

        // Copy Respiratory Report
        function copyBreathingReport() {
            const pacerMins = Math.floor(sessionSeconds / 60).toString().padStart(2, '0');
            const pacerSecs = (sessionSeconds % 60).toString().padStart(2, '0');
            const boltVal = lastBoltScore > 0 ? lastBoltScore.toFixed(1) + 's' : 'Not Tested';
            const boltStatus = document.getElementById('bolt-tier-badge')?.innerText || 'Awaiting Test';

            const report = "=== RESPIRATORY & AUTONOMIC SCORECARD ===\n" +
                "Timestamp: " + new Date().toISOString() + "\n" +
                "Coherence Pacer Frequency: " + currentPreset.bpm.toFixed(1) + " BPM (0.1 Hz Resonance)\n" +
                "Pacing Duration: " + pacerMins + ":" + pacerSecs + " (" + cycleCount + " Completed Cycles)\n" +
                "Body Oxygen Level Test (BOLT): " + boltVal + "\n" +
                "CO2 Tolerance Classification: " + boltStatus + "\n" +
                "Privacy Audit: Runs in Your Browser Local Execution\n" +
                "Generated via ToolkitGen: https://toolkitgen.com/tool/breathing_coherence_trainer";

            if (navigator.clipboard) {
                navigator.clipboard.writeText(report).then(() => {
                    const btn = document.getElementById('btn-copy-report');
                    if (btn) {
                        const old = btn.innerHTML;
                        btn.innerHTML = 'Scorecard Copied!';
                        setTimeout(() => btn.innerHTML = old, 1500);
                    }
                }).catch(() => prompt('Copy your respiratory report:', report));
            } else {
                prompt('Copy your respiratory report:', report);
            }
        }
